window.__VOICE_PACKS__=window.__VOICE_PACKS__||{};window.__VOICE_PACKS__.en={"version":2,"lang":"en","engine":"edge-tts","generatedAt":"2026-11-24T12:57:35.175787+00:00","roles":{"instructor":{"speakerLabel":"教官","speakerLabelEn":"INSTRUCTOR","speechPitch":0.9,"speechRate":1.05},"watcher":{"speakerLabel":"守望者 // 频道 04","speakerLabelEn":"OVERWATCH // CH-04","speechPitch":1.04,"speechRate":1.05},"evac":{"speakerLabel":"撤离一号 // EVAC-01","speakerLabelEn":"EVAC-01","speechPitch":0.95,"speechRate":1.1}},"clips":{"tut_1":{"role":"instructor","priority":3,"cooldownSec":0,"displayText":"欢迎来到 04 号码头。先热身基础机动：WASD 移动、按住 Shift 冲刺、冲刺中按 C 滑铲、按 C 下蹲利用掩体，并按 F 切换战术枪灯。","displayTextEn":"Welcome to Pier 04. Warm up basic movement: WASD to move, hold Shift to sprint, press C while sprinting to slide, press C to crouch in cover, and press F to toggle your weapon light.","mime":"audio/mpeg","data":""},"tut_2":{"role":"instructor","priority":3,"cooldownSec":0,"displayText":"机动良好！按住鼠标右键使用当前瞄具开镜（ADS）并点射 3 发，然后按 [1]/[2] 切换副手枪，再按 [T] 体验现场装卸消音器。","displayTextEn":"Good movement! Hold Right Click to ADS with your optics and fire 3 bursts, press [1]/[2] to swap to your sidearm, then press [T] to attach or detach your suppressor in the field.","mime":"audio/mpeg","data":""},"tut_3":{"role":"instructor","priority":3,"cooldownSec":0,"displayText":"前方 13 米已投放训练靶机！瞄准正中红色光学核心打出 2 倍金色暴击将其击毁，随后按 [R] 将当前弹匣补满。","displayTextEn":"Training drone deployed 13 meters ahead! Aim for the red optical core at center mass for 2x gold crits to destroy it, then press [R] to top off your magazine.","mime":"audio/mpeg","data":""},"tut_4":{"role":"instructor","priority":3,"cooldownSec":0,"displayText":"潜行暗杀演练：按 [Q] 触发战术脉冲扫描标记前方背对你的警戒单位，绕到它身后靠近按 [V] 执行无声处决（免疫普通子弹）！","displayTextEn":"Stealth takedown drill: press [Q] for a tactical pulse scan to tag the sentry ahead facing away from you, flank behind it, and press [V] up close for a silent execution—it's immune to standard rounds!","mime":"audio/mpeg","data":""},"tut_5":{"role":"instructor","priority":3,"cooldownSec":0,"displayText":"防爆盾靶出现！按 [4] 切换投掷道具确认选定 EMP 雷，按 [G] 投出瘫痪护盾后开火击杀！（身旁蓝光补给箱可随时按 [E] 无限补雷）","displayTextEn":"Riot-shield target inbound! Press [4] to cycle throwables and select the EMP grenade, press [G] to throw and disable its shield, then open fire! (Press [E] at the blue supply crate beside you anytime for unlimited refills.)","mime":"audio/mpeg","data":""},"tut_6":{"role":"instructor","priority":3,"cooldownSec":0,"displayText":"善用集装箱制高点与自动探头！沿西侧青色光柱金属斜坡登上集装箱高台（贴箱边按右键开镜即可自动侧身探头）。","displayTextEn":"Use container high ground and auto-lean! Climb the metal ramp marked by the cyan beacon on the west side to reach the container deck—aim down sights near a corner to lean out automatically.","mime":"audio/mpeg","data":""},"tut_7_out":{"role":"instructor","priority":3,"cooldownSec":0,"displayText":"高台视野极佳！现在向西北铁皮仓库（青色光柱入口）移动，进屋体会暴雨隔绝声学并使用演练医疗箱。","displayTextEn":"Great sightlines from up top! Now move to the northwest sheet-metal warehouse (cyan beacon entrance), step inside to hear the rain acoustics muffle, and use the drill medkit.","mime":"audio/mpeg","data":""},"tut_7_in":{"role":"instructor","priority":3,"cooldownSec":0,"displayText":"已进入铁皮仓库！听：雨声瞬变低通闷响且地面干燥。靠近绿色演练医疗箱按 [E] 回满生命值！","displayTextEn":"Inside the sheet-metal warehouse! Listen: the storm drops to a low-pass hum and the deck is dry. Approach the green drill medkit and press [E] to restore full health!","mime":"audio/mpeg","data":""},"tut_8":{"role":"instructor","priority":3,"cooldownSec":0,"displayText":"最终演练：走出南门找到模拟中继器。你可以长按 [E] 无声黑入（不惊动敌人），或按 [G] 贴 C4 强爆摧毁，任选其一即可结业！","displayTextEn":"Final drill: exit the south door and locate the simulated relay. Either hold [E] for a silent hack without alerting hostiles, or press [G] to plant C4 and blow it loud—complete either to graduate!","mime":"audio/mpeg","data":""},"tut_complete":{"role":"instructor","priority":3,"cooldownSec":0,"displayText":"全部 8 项战术演练达标！2 秒后将在南侧泊位满状态重置，正式开启「0/3 中继器切断」实战撤离任务！","displayTextEn":"All 8 tactical drills passed! Resetting at full readiness at the south berth in 2 seconds—live 0/3 relay-sabotage extraction begins now!","mime":"audio/mpeg","data":""},"mission_start":{"role":"watcher","priority":3,"cooldownSec":0,"displayText":"风暴已掩护你渗入 04 号码头。按任意顺序靠近 3 处通信中继器并长按 E 切断信号！","displayTextEn":"The storm masks your insertion into Pier 04. Reach all 3 comms relays in any order and hold [E] to cut the signal!","mime":"audio/mpeg","data":""},"mission_skip":{"role":"watcher","priority":3,"cooldownSec":0,"displayText":"已跳过新手引导，直接切入 04 号码头实战！按任意顺序切断 3 处通信中继器！","displayTextEn":"Briefing skipped—dropping straight into live ops at Pier 04! Take down all 3 comms relays in any order!","mime":"audio/mpeg","data":""},"mission_restart":{"role":"watcher","priority":3,"cooldownSec":0,"displayText":"已重新部署至南侧防波堤。切断全部 3 处中继器后向东北码头撤离！","displayTextEn":"Redeployed to the south breakwater. Cut all 3 relays, then extract at the northeast pier!","mime":"audio/mpeg","data":""},"relay_A_1":{"role":"watcher","priority":3,"cooldownSec":0,"displayText":"中继器 A（西侧集装箱区）已切断 (1/3)！敌方警戒警报已触发，注意拦截无人机与机械犬！","displayTextEn":"Relay A (West Container Yard) offline (1/3)! Hostile alert triggered—watch for interceptor drones and mech hounds!","mime":"audio/mpeg","data":""},"relay_A_2":{"role":"watcher","priority":3,"cooldownSec":0,"displayText":"中继器 A（西侧集装箱区）已切断 (2/3)！只剩最后一处，敌方拦截部队正在逼近！","displayTextEn":"Relay A (West Container Yard) offline (2/3)! One relay left—hostile interceptors closing in!","mime":"audio/mpeg","data":""},"relay_B_1":{"role":"watcher","priority":3,"cooldownSec":0,"displayText":"中继器 B（铁皮仓库内部）已切断 (1/3)！敌方警戒警报已触发，注意拦截无人机与机械犬！","displayTextEn":"Relay B (Warehouse Interior) offline (1/3)! Hostile alert triggered—watch for interceptor drones and mech hounds!","mime":"audio/mpeg","data":""},"relay_B_2":{"role":"watcher","priority":3,"cooldownSec":0,"displayText":"中继器 B（铁皮仓库内部）已切断 (2/3)！只剩最后一处，敌方拦截部队正在逼近！","displayTextEn":"Relay B (Warehouse Interior) offline (2/3)! One relay left—hostile interceptors closing in!","mime":"audio/mpeg","data":""},"relay_C_1":{"role":"watcher","priority":3,"cooldownSec":0,"displayText":"中继器 C（龙门吊控制台）已切断 (1/3)！敌方警戒警报已触发，注意拦截无人机与机械犬！","displayTextEn":"Relay C (Gantry Console) offline (1/3)! Hostile alert triggered—watch for interceptor drones and mech hounds!","mime":"audio/mpeg","data":""},"relay_C_2":{"role":"watcher","priority":3,"cooldownSec":0,"displayText":"中继器 C（龙门吊控制台）已切断 (2/3)！只剩最后一处，敌方拦截部队正在逼近！","displayTextEn":"Relay C (Gantry Console) offline (2/3)! One relay left—hostile interceptors closing in!","mime":"audio/mpeg","data":""},"evac_unlocked":{"role":"evac","priority":3,"cooldownSec":0,"displayText":"全部中继器已离线！码头进入全面封锁，大批机器增援已出动——全速突破并前往东北泊位绿色信号处登船！","displayTextEn":"All relays offline! The dock is in full lockdown with heavy mech reinforcements inbound—break through and board at the green beacon on the northeast berth!","mime":"audio/mpeg","data":""},"tac_low_hp":{"role":"watcher","priority":2,"cooldownSec":16,"displayText":"警告：护甲生命值严重受损！立即寻找掩体或使用医疗箱！","displayTextEn":"Warning: armor and vitals critical! Get to cover or pop a medkit now!","mime":"audio/mpeg","data":""},"tac_ammo_empty":{"role":"watcher","priority":1,"cooldownSec":8,"displayText":"弹匣打空，正在紧急换弹！","displayTextEn":"Mag dry—emergency reload!","mime":"audio/mpeg","data":""},"tac_medkit":{"role":"watcher","priority":1,"cooldownSec":10,"displayText":"应急医疗箱已注入，生命体征回升。","displayTextEn":"Emergency medkit applied. Vitals stabilizing.","mime":"audio/mpeg","data":""},"tac_barrel_kill":{"role":"watcher","priority":1,"cooldownSec":10,"displayText":"危化油桶已引爆，周边机械单位遭重创！","displayTextEn":"Hazmat barrel detonated—nearby hostiles heavily damaged!","mime":"audio/mpeg","data":""},"tac_evac_approach":{"role":"evac","priority":2,"cooldownSec":60,"displayText":"已锁定你的位置！撤离快艇就在东北栈桥泊位，冲刺登船！","displayTextEn":"Got a lock on your transponder! Exfil boat is waiting at the northeast jetty berth—sprint to board!","mime":"audio/mpeg","data":""},"tac_evac_boarding":{"role":"evac","priority":2,"cooldownSec":30,"displayText":"撤离锚链解锁中，掩护好自己，马上起航！","displayTextEn":"Releasing mooring lines—watch your six, we're pulling out!","mime":"audio/mpeg","data":""},"mission_victory":{"role":"evac","priority":3,"cooldownSec":0,"displayText":"全员登船确认！撤离快艇正在驶离 04 号码头，行动圆满成功！","displayTextEn":"All hands aboard! Exfil boat clearing Pier 04—mission accomplished!","mime":"audio/mpeg","data":""},"mission_defeat":{"role":"watcher","priority":3,"cooldownSec":0,"displayText":"失去特遣队员生命信号，04 号码头撤离行动中止。","displayTextEn":"Operator flatlined—Pier 04 extraction aborted.","mime":"audio/mpeg","data":""},"train_timed_start":{"role":"instructor","priority":3,"cooldownSec":0,"displayText":"限时打靶冲刺开始！瞄准靶机红色核心触发暴击，连续击毁叠加连击倍率！","displayTextEn":"Timed target sprint begins! Hit the red optical core for crits and chain kills to stack your combo multiplier!","mime":"audio/mpeg","data":""},"train_timed_end":{"role":"instructor","priority":3,"cooldownSec":0,"displayText":"时间到！本次打靶计时结束，请查看射击评分与暴击统计。","displayTextEn":"Time's up! Range clock stopped—review your accuracy rating and crit telemetry.","mime":"audio/mpeg","data":""},"train_endless_start":{"role":"watcher","priority":3,"cooldownSec":0,"displayText":"无尽波次防线已启动！敌方机械集群正在逼近，清完每波可获得短暂整备回血！","displayTextEn":"Endless defense active! Hostile mech waves inbound—clear each wave for a brief resupply and regen window!","mime":"audio/mpeg","data":""},"train_endless_wave":{"role":"watcher","priority":3,"cooldownSec":0,"displayText":"警戒！新一波机械增援已进入码头防区，利用掩体与危化油桶迎敌！","displayTextEn":"Alert! New wave of mech reinforcements entering the dock perimeter—use cover and hazmat barrels!","mime":"audio/mpeg","data":""},"train_stage_1":{"role":"instructor","priority":3,"cooldownSec":0,"displayText":"关卡一：西区集装箱攻防。利用斜坡抢占高台，消灭敌军并切断 A 号中继器！","displayTextEn":"Stage 1: West Container Yard assault. Take the ramp for high ground, clear hostiles, and cut Relay A!","mime":"audio/mpeg","data":""},"train_stage_2":{"role":"instructor","priority":3,"cooldownSec":0,"displayText":"关卡二：铁皮仓库室内近战。小心机械犬近距突袭，肃清仓库并切断 B 号中继器！","displayTextEn":"Stage 2: Warehouse CQB. Watch for close-quarters mech hound rushes, clear the bay, and cut Relay B!","mime":"audio/mpeg","data":""},"train_stage_3":{"role":"instructor","priority":3,"cooldownSec":0,"displayText":"关卡三：东侧龙门吊制高点。善用危险油桶连锁爆破，肃清敌军并切断 C 号中继器！","displayTextEn":"Stage 3: East Gantry high ground. Chain hazmat barrel blasts to clear the yard and cut Relay C!","mime":"audio/mpeg","data":""},"train_stage_4":{"role":"evac","priority":3,"cooldownSec":0,"displayText":"关卡四：终局全面封锁突围！全速冲破机器防线，前往东北泊位长按 E 登船撤离！","displayTextEn":"Stage 4: Final lockdown breakout! Punch through the mech perimeter and hold [E] at the northeast berth to exfil!","mime":"audio/mpeg","data":""},"train_stage_clear":{"role":"instructor","priority":3,"cooldownSec":0,"displayText":"关卡练习达标！区域目标已全部肃清，表现干脆利落！","displayTextEn":"Stage drill complete! Sector objectives neutralized—clean execution!","mime":"audio/mpeg","data":""},"relay_stealth_clean":{"role":"watcher","priority":3,"cooldownSec":0,"displayText":"中继节点已无声黑入！敌方巡防网尚未察觉，继续保持幽灵渗入节奏。","displayTextEn":"Relay node silently hacked! Patrol grid remains unaware—maintain ghost insertion.","mime":"audio/mpeg","data":""},"relay_c4_loud":{"role":"watcher","priority":3,"cooldownSec":0,"displayText":"高爆破拆已瞬间摧毁中继核心！巨响已惊动码头防区，准备迎击追猎小队！","displayTextEn":"C4 charge blew the relay core! Blast alerted the dock perimeter—brace for hunter squads!","mime":"audio/mpeg","data":""},"alarm_compromised":{"role":"watcher","priority":2,"cooldownSec":18,"displayText":"警告：敌方侦察单位已发出警报信号，周边增援小队正在合围！","displayTextEn":"Warning: hostile recon unit transmitted an alarm—nearby reinforcements converging!","mime":"audio/mpeg","data":""},"enemy_shield_warn":{"role":"watcher","priority":2,"cooldownSec":24,"displayText":"发现防爆盾重装机兵！正面装甲弹反常规子弹，建议侧翼绕后、投掷 EMP 破盾或炸桶！","displayTextEn":"Heavy riot-shield mech spotted! Frontal armor deflects standard rounds—flank behind, throw EMP, or detonate a barrel!","mime":"audio/mpeg","data":""},"enemy_laser_warn":{"role":"watcher","priority":2,"cooldownSec":20,"displayText":"小心高处红线激光锁定！高台狙击无人机正在蓄能，立即滑铲进掩体或反狙击！","displayTextEn":"Watch the high-angle laser lock! Elevated sniper drone charging—slide into cover or counter-snipe now!","mime":"audio/mpeg","data":""},"evac_holdout_start":{"role":"evac","priority":3,"cooldownSec":0,"displayText":"全部中继器已离线！我艇正在全速抵近东北栈桥，守住泊位 30 秒直到接应泊靠！","displayTextEn":"All relays offline! Inbound hot to the northeast jetty—hold the berth for 30 seconds until we dock!","mime":"audio/mpeg","data":""},"evac_holdout_15s":{"role":"evac","priority":2,"cooldownSec":30,"displayText":"还剩 15 秒抵达接应泊位！压制东北方向来敌，守住栈桥入口！","displayTextEn":"15 seconds to dock! Suppress hostiles from the northeast and hold the jetty approach!","mime":"audio/mpeg","data":""},"ammo_crate_resupply":{"role":"watcher","priority":1,"cooldownSec":10,"displayText":"码头战术弹药箱已开启，主副武器备弹与战术投掷物已补充。","displayTextEn":"Tactical ammo crate opened—primary, sidearm reserve, and throwables replenished.","mime":"audio/mpeg","data":""},"ammo_low_reserve":{"role":"watcher","priority":2,"cooldownSec":16,"displayText":"警告：备弹存量告急！请切换副手枪或寻找码头周边绿色战术弹药箱。","displayTextEn":"Warning: reserve ammo critical! Swap to your USP-9 sidearm or hit a green tactical ammo crate on the pier.","mime":"audio/mpeg","data":""},"endless_airdrop_ready":{"role":"watcher","priority":3,"cooldownSec":8,"displayText":"波次间隙整备开启！空投战术模块已投放，选择一项强化继续迎敌！","displayTextEn":"Inter-wave resupply online! Tactical airdrop module ready—select an upgrade and hold the line!","mime":"audio/mpeg","data":""},"mission_rank_s":{"role":"evac","priority":3,"cooldownSec":0,"displayText":"全员安全登船！指挥部授予本次行动最高 S 级特战评价，干得太漂亮了！","displayTextEn":"All hands safely aboard! Command awards top S-rank spec-ops rating—outstanding work!","mime":"audio/mpeg","data":""},"train_stage_5":{"role":"instructor","priority":3,"cooldownSec":0,"displayText":"关卡五：潜行暗杀与发报打断演练。利用 T 键消音器、V 键背后处决与诱饵器无声切断中继器！","displayTextEn":"Stage 5: Stealth takedown and comms-jam drill. Use your [T] suppressor, [V] backstab execution, and decoys to sever the relay silently!","mime":"audio/mpeg","data":""},"train_stage_6":{"role":"instructor","priority":3,"cooldownSec":0,"displayText":"关卡六：重装破盾与反狙击演练。用 G 键 EMP 瘫痪防爆盾兵，利用滑铲躲避激光狙击并肃清战区！","displayTextEn":"Stage 6: Heavy shield-break and counter-snipe drill. Stun riot-shield mechs with [G] EMP, slide past laser locks, and clear the zone!","mime":"audio/mpeg","data":""}}};
